mapper.select:
select u.id as user_id, u.login_name as login_name, u.nick_name as nick_name, r.id as role_id, r.role_name as role_name, rm.app_id as app_id, a.app_name as app_name, rm.permission as permission, rm.data_scope as data_scope, ru.expire_time as expire_time from system_role_user ru inner join system_user_base u on u.id = ru.user_id and u.deleted_flag = 'N' inner join system_role r on r.id = ru.role_id and r.deleted_flag = 'N' and r.status = 1 left join system_role_menu rm on rm.role_id = r.id and rm.deleted_flag = 'N' left join system_app_info a on a.id = rm.app_id and a.deleted_flag = 'N'
ru.deleted_flag = 'N' and (ru.expire_time is null or ru.expire_time > ) and (u.status is null or u.status != 3) and r.organization_id = #{organizationId} and ru.user_id = #{userId} and ru.role_id = #{roleId}
order by u.login_name, r.role_name, rm.app_id, rm.permission
